# "org" ensures this Service is used with the correct Serverless Framework Access Key.
org: winaifinance
service: reserwaya-back
frameworkVersion: ">=4.0.0"

provider:
  name: aws
  runtime: nodejs22.x
  region: us-east-1
  stage: prod
  environment:
    NODE_ENV: production
    MONGODB_URI: ${env:MONGODB_URI}
    OIDC_ISSUER: ${env:OIDC_ISSUER}
    OIDC_CLIENT_ID: ${env:OIDC_CLIENT_ID}
    OIDC_ADMIN_BASE_URL: ${env:OIDC_ADMIN_BASE_URL}
    OIDC_ADMIN_CLIENT_ID: ${env:OIDC_ADMIN_CLIENT_ID}
    OIDC_ADMIN_CLIENT_SECRET: ${env:OIDC_ADMIN_CLIENT_SECRET}
    PAYMENT_PROVIDER: ${env:PAYMENT_PROVIDER, 'mock'}
    WOMPI_ENVIRONMENT: ${env:WOMPI_ENVIRONMENT, 'test'}
    WOMPI_EVENTS_SECRET: ${env:WOMPI_EVENTS_SECRET, ''}
    WOMPI_PUBLIC_KEY: ${env:WOMPI_PUBLIC_KEY, ''}
    WOMPI_PRIVATE_KEY: ${env:WOMPI_PRIVATE_KEY, ''}
    WOMPI_INTEGRITY_SECRET: ${env:WOMPI_INTEGRITY_SECRET, ''}
    PAYU_API_KEY: ${env:PAYU_API_KEY, ''}
    PAYU_API_SECRET: ${env:PAYU_API_SECRET, ''}
    PAYU_MERCHANT_ID: ${env:PAYU_MERCHANT_ID, ''}
    PAYU_ACCOUNT_ID: ${env:PAYU_ACCOUNT_ID, ''}
    PAYU_BASE_URL: ${env:PAYU_BASE_URL, 'https://api.payulatam.com'}
    FRONT_BASE_URL: ${env:FRONT_BASE_URL, 'https://d1ydnh3hbo1zxr.cloudfront.net'}
    PAYMENT_SESSION_SECRET: ${env:PAYMENT_SESSION_SECRET, 'dev-reservaya-payment-session-secret'}
    WHATSAPP_PROVIDER: ${env:WHATSAPP_PROVIDER, 'mock'}
    WHATSAPP_BOT_SECRET: ${env:WHATSAPP_BOT_SECRET, ''}
    WHATSAPP_EVENTS_ENDPOINT: ${env:WHATSAPP_EVENTS_ENDPOINT, ''}
    CANCELLATION_PROCESSING_FEE_RATE: ${env:CANCELLATION_PROCESSING_FEE_RATE, '0'}

functions:
  api:
    handler: dist-lambda/index.lambdaHandler
    events:
      - httpApi: "*"
    timeout: 30
    memorySize: 256

  expire-pending-payments:
    handler: dist-lambda/scheduled.expiredPaymentsHandler
    events:
      - schedule: rate(5 minutes)
    timeout: 60
    memorySize: 256

  repair-time-slots:
    handler: dist-lambda/scheduled.repairTimeSlotsHandler
    events:
      - schedule: rate(15 minutes)
    timeout: 60
    memorySize: 256

package:
  patterns:
    - '!**'
    - 'dist-lambda/**'
